select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('log-code','کد رویداد','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',false,30,'{}'),('version','نسخه سند','text',false,40,'{}'),('actor','کاربر / عامل','text',true,50,'{}'),('actor-type','نوع عامل','select',true,60,'{"options":["کاربر","نقش","سرویس","سامانه","مهمان"]}'),('organization','سازمان / واحد','text',false,70,'{}'),('action-type','نوع عملیات','select',true,80,'{"options":["مشاهده","دانلود","چاپ","اشتراک‌گذاری","ویرایش","تأیید","انتشار","بایگانی","بازگردانی","امحا","تلاش ناموفق"]}'),('access-result','نتیجه دسترسی','select',true,90,'{"options":["موفق","رد شده","ناموفق"]}'),('access-date','تاریخ و زمان','text',true,100,'{}'),('ip-address','نشانی IP','text',false,110,'{}'),('user-agent','مشخصات عامل','text',false,120,'{}'),('source-reference','مرجع درخواست','text',false,130,'{}'),('reason','علت / توضیح دسترسی','text',false,140,'{}'),('sensitivity','حساسیت سند','select',false,150,'{"options":["عمومی","داخلی","محرمانه","بسیار محرمانه"]}'),('retention-status','وضعیت نگهداری لاگ','select',true,160,'{"options":["فعال","در بایگانی","منقضی","مجاز به حذف"]}'),('notes','یادداشت','textarea',false,170,'{}')
) v(k,t,ft,r,s,o) where m.code='47-document-access-log' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
