insert into platform_modules(code,title,is_active) values ('47-document-access-log','ثبت و پایش دسترسی مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده رویدادها','modules:47-document-access-log:read'),('write','ثبت رویداد','modules:47-document-access-log:write'),('delete','حذف رویداد','modules:47-document-access-log:delete'),('archive','بایگانی لاگ','modules:47-document-access-log:archive'),('retain','تمدید نگهداری','modules:47-document-access-log:retain'),('export','خروجی گزارش','modules:47-document-access-log:export')) v(a,t,p) where m.code='47-document-access-log' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;